INSERT INTO "MsPhishingQuestion" (
  "id", "sequence", "senderName", "senderEmail", "senderAsset", "subject", "preview", "greeting", "body", "action", "attachmentName", "attachmentAsset", "suspicious", "explanation", "clues", "updatedAt"
) VALUES
('voice-note-deepfake', 51, 'Calvin Wu', 'calvin.wu@voice-message.click', '/assets/Game1/characters/chara1.png', 'Pesan suara darurat dari Calvin', 'Calvin meminta bantuan uang melalui rekaman suara.', 'Hai, ini darurat,', 'Aku sedang meminjam ponsel orang lain. Dengarkan rekaman terlampir lalu kirim saldo ke nomor baru ini. Jangan hubungi nomor lamaku karena sedang disadap.', 'Transfer sekarang ke dompet digital 0812-0000-7788.', 'PesanSuaraCalvin.zip', '/assets/Shared/Game/FileZip.png', true, 'Suara dapat dipalsukan. Permintaan uang, larangan memverifikasi melalui kanal lama, dan arsip asing adalah tanda penipuan.', '[{"id":"sender","label":"Domain pesan palsu","text":"Alamat memakai voice-message.click, bukan sekolah.id."},{"id":"body","label":"Melarang verifikasi","text":"Pesan meminta penerima tidak menghubungi nomor Calvin yang biasa."},{"id":"attachment","label":"Arsip suara mencurigakan","text":"Rekaman dikirim sebagai berkas ZIP."}]'::jsonb, CURRENT_TIMESTAMP),
('club-badge-safe', 52, 'Naya Bloom', 'naya.bloom@komunitasseni.id', '/assets/Game1/characters/chara11.png', 'Lencana peserta kelas ilustrasi', 'Lencana digital tersedia di profil komunitas.', 'Halo peserta,', 'Terima kasih sudah menyelesaikan kelas ilustrasi. Lencana peserta sudah ditambahkan langsung ke profil komunitasmu. Tidak ada data yang perlu dikirim lewat email.', 'Lihat profil: https://komunitasseni.id/profil', NULL, NULL, false, 'Pengirim dan tautan berasal dari domain komunitas resmi serta tidak meminta informasi rahasia.', '[]'::jsonb, CURRENT_TIMESTAMP),
('ewallet-refund-scam', 53, 'Maya Putri', 'maya.putri@saldo-kembali.help', '/assets/Game1/characters/chara2.png', 'Saldo dompet digitalmu dikembalikan', 'Konfirmasi PIN untuk menerima pengembalian saldo.', 'Pengguna terpilih,', 'Transaksi kemarin dibatalkan dan saldo siap dikembalikan. Masukkan nomor ponsel, PIN, dan OTP pada formulir agar dana tidak hangus malam ini.', 'Ambil saldo: https://refund-wallet.help/claim', NULL, NULL, true, 'Penyedia dompet digital tidak meminta PIN dan OTP untuk mengembalikan saldo.', '[{"id":"sender","label":"Pengirim palsu","text":"Alamat menggunakan domain saldo-kembali.help."},{"id":"body","label":"Meminta PIN dan OTP","text":"Pesan meminta dua rahasia autentikasi sekaligus."},{"id":"action","label":"Formulir asing","text":"Tautan mengarah ke refund-wallet.help."}]'::jsonb, CURRENT_TIMESTAMP),
('school-cloud-maintenance-safe', 54, 'Pak Dimas', 'dimas@sekolah.id', '/assets/Game1/characters/chara4.png', 'Pemeliharaan penyimpanan sekolah', 'Portal dokumen tidak tersedia Sabtu pagi.', 'Anak-anak,', 'Layanan dokumen sekolah akan menjalani pemeliharaan pada Sabtu pukul 06.00 sampai 08.00. Simpan pekerjaanmu sebelum waktu tersebut. Admin tidak akan meminta kata sandi.', 'Status layanan: https://status.sekolah.id', NULL, NULL, false, 'Pemberitahuan memakai domain resmi, menjelaskan jadwal, dan tidak meminta kredensial.', '[]'::jsonb, CURRENT_TIMESTAMP),
('fake-ai-homework-tool', 55, 'Raka Pradana', 'raka.pradana@ai-tugas-premium.pro', '/assets/Game1/characters/chara3.png', 'AI premium gratis untuk mengerjakan ujian', 'Instal alat rahasia sebelum lisensinya habis.', 'Bro,', 'Aku menemukan AI yang bisa menjawab ujian secara otomatis. Matikan antivirus, jalankan installer, lalu login memakai akun sekolah supaya semua fitur terbuka.', 'Aktifkan lewat lampiran.', 'AI-Ujian-Premium.exe', '/assets/Shared/Game/FileZip.png', true, 'Program ujian ilegal yang meminta antivirus dimatikan dan akun sekolah berisiko mencuri data serta memasang malware.', '[{"id":"sender","label":"Domain tidak dikenal","text":"Alamat menggunakan ai-tugas-premium.pro."},{"id":"body","label":"Instruksi berbahaya","text":"Pesan meminta antivirus dimatikan dan akun sekolah digunakan."},{"id":"attachment","label":"Program tak tepercaya","text":"Lampiran berupa berkas .exe."}]'::jsonb, CURRENT_TIMESTAMP),
('library-room-safe', 56, 'Bu Ratna', 'ratna@sekolah.id', '/assets/Game1/characters/chara14.png', 'Reservasi ruang baca dikonfirmasi', 'Ruang diskusi 2 tersedia pukul 13.00.', 'Halo Calvin,', 'Reservasi ruang diskusi 2 untuk tugas kelompok sudah dikonfirmasi. Datang lima menit lebih awal dan tunjukkan kartu pelajar di meja petugas.', 'Kelola reservasi: https://perpus.sekolah.id/reservasi', NULL, NULL, false, 'Pesan sesuai konteks perpustakaan dan tindakan dilakukan melalui layanan resmi sekolah.', '[]'::jsonb, CURRENT_TIMESTAMP),
('esports-sponsor-scam', 57, 'PixelRex', 'pixelrex@sponsor-esports.vip', '/assets/Game1/characters/chara10.png', 'Kontrak sponsor esports untuk timmu', 'Bayar biaya verifikasi untuk menerima perangkat gaming.', 'Halo kapten tim,', 'Tim kalian dipilih menjadi ambassador. Kirim foto identitas, alamat rumah, dan biaya verifikasi Rp150.000 sebelum kontrak diberikan.', 'Daftar: https://sponsor-esports.vip/ambassador', NULL, NULL, true, 'Sponsor yang meminta pembayaran dan identitas sebelum memberikan kontrak kemungkinan besar merupakan penipuan.', '[{"id":"sender","label":"Domain sponsor asing","text":"Alamat menggunakan sponsor-esports.vip."},{"id":"body","label":"Meminta biaya dan identitas","text":"Pesan meminta pembayaran, foto identitas, dan alamat rumah."},{"id":"action","label":"Pendaftaran tidak resmi","text":"Tautan bukan berasal dari platform turnamen yang dikenal."}]'::jsonb, CURRENT_TIMESTAMP),
('parent-letter-safe', 58, 'Bu Aisyah', 'aisyah@sekolah.id', '/assets/Game1/characters/chara9.png', 'Surat kegiatan untuk orang tua', 'Surat resmi tersedia di portal siswa.', 'Yth. siswa,', 'Surat kegiatan luar sekolah sudah tersedia. Silakan unduh melalui portal dan berikan kepada orang tua. Formulir persetujuan dikembalikan langsung ke wali kelas.', 'Unduh: https://portal.sekolah.id/surat-kegiatan', 'surat-kegiatan.pdf', '/assets/Shared/Game/FileText.png', false, 'Pengirim, portal, lampiran, dan prosedurnya konsisten dengan komunikasi resmi sekolah.', '[]'::jsonb, CURRENT_TIMESTAMP),
('browser-extension-phish', 59, 'Alex Support', 'support@browser-sekolah.store', '/assets/Game1/characters/chara12.png', 'Ekstensi wajib untuk membuka nilai', 'Pasang ekstensi dan izinkan membaca semua data browser.', 'Halo siswa,', 'Portal nilai kini memerlukan ekstensi keamanan. Pasang dari tautan berikut dan izinkan akses membaca kata sandi serta riwayat browser.', 'Pasang: https://browser-sekolah.store/extension', NULL, NULL, true, 'Ekstensi yang meminta akses seluruh data browser dari toko tidak resmi dapat mencuri kredensial.', '[{"id":"sender","label":"Support palsu","text":"Alamat memakai browser-sekolah.store."},{"id":"body","label":"Izin berlebihan","text":"Ekstensi meminta akses kata sandi dan riwayat browser."},{"id":"action","label":"Toko ekstensi palsu","text":"Pemasangan tidak melalui toko browser resmi."}]'::jsonb, CURRENT_TIMESTAMP),
('eco-certificate-safe', 60, 'Sari Mahendra', 'sari.mahendra@komunitashijau.id', '/assets/Game1/characters/chara13.png', 'Sertifikat relawan sudah tersedia', 'Unduh sertifikat kegiatan bersih sungai.', 'Halo relawan,', 'Sertifikat kegiatan bersih sungai sudah tersedia pada halaman anggota. Nama pada sertifikat mengikuti profil komunitas dan dapat diperbaiki melalui pengaturan akun.', 'Unduh: https://komunitashijau.id/sertifikat', NULL, NULL, false, 'Pesan berasal dari komunitas resmi dan tidak meminta data sensitif melalui email.', '[]'::jsonb, CURRENT_TIMESTAMP),
('attendance-qr-phish', 61, 'Arman Setiawan', 'arman.setiawan@absensi-sekolah.click', '/assets/Game1/characters/chara5.png', 'Absensi susulan wajib lewat QR', 'Pindai QR lalu login sebelum dianggap tidak hadir.', 'Siswa,', 'Data absensimu hilang. Pindai QR terlampir dan masukkan akun sekolah dalam lima menit agar tidak mendapat hukuman.', 'Pindai sekarang.', 'QR-Absensi.png', '/assets/Shared/Game/FilePhoto.png', true, 'QR dapat menyembunyikan situs pencuri akun. Tekanan waktu dan domain pengirim palsu memperkuat tanda phishing.', '[{"id":"sender","label":"Domain absensi palsu","text":"Alamat memakai absensi-sekolah.click."},{"id":"body","label":"Ancaman mendesak","text":"Pesan mengancam hukuman dan meminta login dalam lima menit."},{"id":"attachment","label":"QR login tak terduga","text":"QR meminta autentikasi di luar portal resmi."}]'::jsonb, CURRENT_TIMESTAMP),
('art-license-safe', 62, 'Naya Bloom', 'naya.bloom@komunitasseni.id', '/assets/Game1/characters/chara11.png', 'Izin penggunaan karya untuk katalog', 'Tinjau judul dan nama kreator di halaman komunitas.', 'Halo Naya,', 'Karyamu dipilih untuk katalog bulanan. Silakan periksa judul dan nama kreator pada halaman resmi. Tidak ada pengalihan hak cipta atau biaya penerbitan.', 'Tinjau: https://komunitasseni.id/katalog/review', NULL, NULL, false, 'Permintaan transparan, tanpa biaya, dan menggunakan domain komunitas resmi.', '[]'::jsonb, CURRENT_TIMESTAMP),
('fake-teacher-voice-call', 63, 'Pak Budi Santoso', 'budi.santoso@guru-urgent.live', '/assets/Game1/characters/chara8.png', 'Pak Budi butuh kode OTP sekarang', 'Rekaman suara meminta OTP untuk membuka dokumen nilai.', 'Dengarkan baik-baik,', 'Saya tidak bisa masuk ke akun guru dan membutuhkan kode OTP yang masuk ke ponselmu. Kirim kodenya agar nilai kelas bisa diselamatkan.', 'Balas email ini secepatnya.', 'Instruksi-Guru.mp3.zip', '/assets/Shared/Game/FileZip.png', true, 'Nama dan suara dapat ditiru. Guru tidak memerlukan OTP milik siswa untuk mengakses akun guru.', '[{"id":"sender","label":"Domain guru palsu","text":"Alamat memakai guru-urgent.live, bukan sekolah.id."},{"id":"body","label":"Meminta OTP","text":"Pesan meminta kode OTP milik siswa."},{"id":"attachment","label":"Rekaman dalam arsip","text":"Audio dikirim sebagai arsip ZIP yang tak terduga."}]'::jsonb, CURRENT_TIMESTAMP),
('math-remedial-safe', 64, 'Pak Budi Santoso', 'budi.santoso@sekolah.id', '/assets/Game1/characters/chara8.png', 'Jadwal remedial matematika', 'Pilih salah satu sesi melalui portal kelas.', 'Halo,', 'Sesi remedial tersedia Selasa dan Kamis setelah sekolah. Pilih jadwal melalui portal kelas. Saya tidak akan meminta jawaban ujian atau kata sandi lewat email.', 'Pilih jadwal: https://portal.sekolah.id/remedial-matematika', NULL, NULL, false, 'Pesan memakai kanal resmi dan tidak meminta kredensial atau data yang tidak relevan.', '[]'::jsonb, CURRENT_TIMESTAMP),
('sim-swap-scam', 65, 'Alex Support', 'support@nomor-aman.help', '/assets/Game1/characters/chara12.png', 'Nomor ponselmu akan dipindahkan', 'Kirim OTP agar SIM tidak diambil alih.', 'Pelanggan,', 'Ada permintaan penggantian kartu SIM. Untuk membatalkannya, balas dengan nomor identitas, PIN akun, dan OTP yang baru diterima.', 'Balas dalam 10 menit.', NULL, NULL, true, 'Pesan menggunakan ketakutan terhadap SIM swap untuk memperoleh data yang justru dibutuhkan penyerang.', '[{"id":"sender","label":"Domain support palsu","text":"Alamat memakai nomor-aman.help."},{"id":"body","label":"Meminta identitas dan OTP","text":"Pesan meminta nomor identitas, PIN, dan OTP."},{"id":"action","label":"Tekanan waktu","text":"Penerima diberi waktu hanya 10 menit."}]'::jsonb, CURRENT_TIMESTAMP),
('game-security-safe', 66, 'PixelRex', 'pixelrex@gamehub.id', '/assets/Game1/characters/chara10.png', 'Aktifkan keamanan akun turnamen', 'Gunakan pengaturan keamanan di aplikasi resmi.', 'Halo tim,', 'Sebelum turnamen, aktifkan autentikasi dua langkah melalui aplikasi GameHub. Jangan pernah mengirim kode cadangan kepada admin atau pemain lain.', 'Panduan: https://gamehub.id/keamanan', NULL, NULL, false, 'Pesan memakai domain resmi dan memberikan panduan keamanan tanpa meminta kode rahasia.', '[]'::jsonb, CURRENT_TIMESTAMP),
('internship-offer-scam', 67, 'Maya Putri', 'maya.putri@magang-cepat.work', '/assets/Game1/characters/chara2.png', 'Magang bergaji tinggi tanpa seleksi', 'Kirim dokumen identitas dan biaya seragam hari ini.', 'Pelamar terpilih,', 'Kamu diterima sebagai intern meski belum melamar. Kirim foto kartu keluarga, kartu pelajar, rekening, dan biaya seragam agar kontrak diproses.', 'Daftar: https://magang-cepat.work/onboarding', NULL, NULL, true, 'Penerimaan tanpa lamaran yang meminta banyak dokumen dan biaya di muka merupakan pola penipuan lowongan.', '[{"id":"sender","label":"Perekrut tidak dikenal","text":"Alamat memakai magang-cepat.work."},{"id":"body","label":"Data berlebihan dan biaya","text":"Pesan meminta dokumen keluarga, rekening, dan pembayaran."},{"id":"action","label":"Onboarding palsu","text":"Tautan bukan milik perusahaan yang dapat diverifikasi."}]'::jsonb, CURRENT_TIMESTAMP),
('alumni-webinar-safe', 68, 'Pak Dimas', 'dimas@sekolah.id', '/assets/Game1/characters/chara4.png', 'Webinar alumni tentang karier digital', 'Pendaftaran tersedia melalui portal sekolah.', 'Halo siswa,', 'Alumni sekolah akan berbagi pengalaman tentang karier digital pada Jumat. Pendaftaran gratis dan hanya membutuhkan pilihan kelas pada portal.', 'Daftar: https://portal.sekolah.id/webinar-alumni', NULL, NULL, false, 'Kegiatan dapat diverifikasi melalui portal sekolah dan tidak meminta data sensitif.', '[]'::jsonb, CURRENT_TIMESTAMP),
('family-calendar-safe', 69, 'Calvin Wu', 'calvin.wu@sekolah.id', '/assets/Game1/characters/chara1.png', 'Kalender tugas kelompok diperbarui', 'Tenggat presentasi dipindah ke hari Senin.', 'Hai tim,', 'Aku sudah memperbarui kalender tugas kelompok karena ruang presentasi baru tersedia hari Senin. Cek perubahan melalui kalender sekolah.', 'Kalender: https://kalender.sekolah.id/tugas-kelompok', NULL, NULL, false, 'Pengirim dikenal dan tautan menggunakan subdomain resmi sekolah.', '[]'::jsonb, CURRENT_TIMESTAMP),
('fake-drive-share', 70, 'Calvin Wu', 'calvin.wu@dokumen-share.cloud', '/assets/Game1/characters/chara1.png', 'Calvin membagikan jawaban ujian', 'Login untuk membuka dokumen rahasia.', 'Halo,', 'Aku menemukan jawaban ujian besok. Login dengan akun sekolah pada halaman berbagi ini sebelum dokumennya dihapus.', 'Buka: https://dokumen-share.cloud/ujian-rahasia', NULL, NULL, true, 'Konteks tidak etis, domain asing, dan permintaan login sekolah menunjukkan upaya pencurian akun.', '[{"id":"sender","label":"Alamat Calvin palsu","text":"Alamat bukan calvin.wu@sekolah.id."},{"id":"body","label":"Umpan jawaban ujian","text":"Pesan memakai dokumen rahasia sebagai umpan."},{"id":"action","label":"Login di cloud asing","text":"Tautan meminta akun sekolah pada domain dokumen-share.cloud."}]'::jsonb, CURRENT_TIMESTAMP),
('parcel-photo-scam', 71, 'Reno Aditya', 'reno.aditya@kurir-foto.click', '/assets/Game1/characters/chara6.png', 'Foto paket gagal dikirim', 'Buka foto paket dan konfirmasi alamat.', 'Penerima,', 'Kurir gagal menemukan rumahmu. Buka foto paket terlampir lalu masukkan alamat lengkap dan data kartu untuk penjadwalan ulang.', 'Konfirmasi: https://kurir-foto.click/reschedule', 'FotoPaket.jpg.exe', '/assets/Shared/Game/FileZip.png', true, 'Nama file menyamarkan program sebagai foto, sementara situs meminta alamat dan data kartu.', '[{"id":"sender","label":"Domain kurir palsu","text":"Alamat memakai kurir-foto.click."},{"id":"action","label":"Formulir meminta kartu","text":"Penjadwalan ulang mengarah ke situs asing yang meminta pembayaran."},{"id":"attachment","label":"Ekstensi ganda berbahaya","text":"Lampiran berakhir dengan .jpg.exe."}]'::jsonb, CURRENT_TIMESTAMP),
('class-photo-safe', 72, 'Raka Pradana', 'raka.pradana@sekolah.id', '/assets/Game1/characters/chara3.png', 'Pilihan foto untuk majalah kelas', 'Tinjau foto yang sudah disamarkan.', 'Hai teman-teman,', 'Aku mengunggah tiga pilihan foto untuk majalah kelas. Nama lengkap pada papan sudah diburamkan. Beri suara melalui halaman kelas.', 'Pilih: https://portal.sekolah.id/kelas/foto', 'pratinjau-foto.png', '/assets/Shared/Game/FilePhoto.png', false, 'Pengirim dikenal, informasi pribadi telah disamarkan, dan voting dilakukan melalui portal resmi.', '[]'::jsonb, CURRENT_TIMESTAMP),
('emergency-contact-phish', 73, 'Bu Aisyah', 'aisyah@kontak-darurat.support', '/assets/Game1/characters/chara9.png', 'Kontak daruratmu terhapus', 'Kirim alamat rumah dan identitas orang tua sekarang.', 'Yth. siswa,', 'Database sekolah rusak. Balas dengan alamat rumah, nomor identitas orang tua, foto kartu keluarga, dan nomor telepon agar kamu tetap boleh masuk kelas.', 'Balas sebelum besok pagi.', NULL, NULL, true, 'Sekolah tidak meminta paket data keluarga yang sensitif melalui balasan email dari domain asing.', '[{"id":"sender","label":"Alamat administrasi palsu","text":"Alamat memakai kontak-darurat.support."},{"id":"body","label":"Meminta data keluarga sensitif","text":"Pesan meminta alamat, identitas orang tua, dan kartu keluarga."},{"id":"action","label":"Ancaman akses kelas","text":"Pesan mengancam siswa tidak boleh masuk kelas."}]'::jsonb, CURRENT_TIMESTAMP),
('library-ticket-change-safe', 74, 'Bu Ratna', 'ratna@sekolah.id', '/assets/Game1/characters/chara14.png', 'Nomor tiket reservasi diperbarui', 'Gunakan tiket baru saat mengambil buku.', 'Halo,', 'Karena perpindahan rak, nomor tiket reservasi berubah menjadi BK-3107. Tidak perlu membalas email ini. Tunjukkan tiket pada aplikasi perpustakaan.', 'Buka aplikasi: https://perpus.sekolah.id/reservasi/BK-3107', NULL, NULL, false, 'Perubahan tiket dapat diverifikasi pada aplikasi resmi dan tidak meminta data tambahan.', '[]'::jsonb, CURRENT_TIMESTAMP),
('digital-inheritance-scam', 75, 'Nico Grey', 'nico.grey@warisan-digital.top', '/assets/Game1/characters/chara7.png', 'Kamu menerima warisan aset digital', 'Bayar pajak kecil untuk membuka dompet bernilai besar.', 'Penerima manfaat,', 'Seseorang dengan nama keluarga yang sama meninggalkan aset digital untukmu. Kirim identitas dan bayar pajak Rp300.000 agar kunci dompet dikirim.', 'Klaim: https://warisan-digital.top/claim', NULL, NULL, true, 'Warisan tak terduga yang meminta pembayaran awal dan identitas adalah penipuan uang muka.', '[{"id":"sender","label":"Pengirim tidak dapat diverifikasi","text":"Alamat memakai warisan-digital.top."},{"id":"body","label":"Meminta biaya di muka","text":"Pesan meminta pajak sebelum aset diberikan."},{"id":"action","label":"Situs klaim asing","text":"Tautan klaim tidak terkait lembaga resmi."}]'::jsonb, CURRENT_TIMESTAMP),
('passwordless-login-safe', 76, 'Alex Support', 'support@layanan.id', '/assets/Game1/characters/chara12.png', 'Login tanpa kata sandi diaktifkan', 'Perubahan keamanan dilakukan dari perangkatmu.', 'Halo,', 'Login tanpa kata sandi berhasil diaktifkan dari aplikasi resmi. Jika ini bukan tindakanmu, buka aplikasi secara langsung dan pilih Batalkan Perubahan. Jangan kirim kode pemulihan kepada siapa pun.', 'Pusat keamanan: https://layanan.id/keamanan', NULL, NULL, false, 'Pemberitahuan memakai domain resmi dan mengarahkan pengguna ke aplikasi tanpa meminta rahasia.', '[]'::jsonb, CURRENT_TIMESTAMP),
('fake-antivirus-invoice', 77, 'Arman Setiawan', 'arman.setiawan@antivirus-tagihan.store', '/assets/Game1/characters/chara5.png', 'Tagihan antivirus otomatis Rp1.500.000', 'Batalkan lewat aplikasi terlampir hari ini.', 'Pelanggan,', 'Langganan antivirus diperpanjang otomatis. Untuk membatalkan, jalankan aplikasi refund terlampir sebagai administrator dan masukkan data kartu.', 'Jalankan aplikasi refund.', 'AntivirusRefund.msi', '/assets/Shared/Game/FileZip.png', true, 'Tagihan mengejutkan digunakan untuk mendorong korban menjalankan installer dan memberikan data kartu.', '[{"id":"sender","label":"Domain tagihan palsu","text":"Alamat memakai antivirus-tagihan.store."},{"id":"body","label":"Meminta hak administrator dan kartu","text":"Pesan meminta aplikasi dijalankan sebagai administrator lalu meminta data kartu."},{"id":"attachment","label":"Installer mencurigakan","text":"Lampiran berupa berkas .msi."}]'::jsonb, CURRENT_TIMESTAMP),
('volunteer-schedule-safe', 78, 'Sari Mahendra', 'sari.mahendra@komunitashijau.id', '/assets/Game1/characters/chara13.png', 'Pembagian jadwal relawan akhir pekan', 'Periksa lokasi dan waktu giliranmu.', 'Halo relawan,', 'Jadwal akhir pekan sudah dibagi. Lokasi kegiatan adalah taman kota, tempat umum yang sama seperti bulan lalu. Perubahan giliran dilakukan melalui halaman anggota.', 'Jadwal: https://komunitashijau.id/relawan/jadwal', NULL, NULL, false, 'Isi sesuai kegiatan komunitas, lokasi bersifat publik, dan domainnya resmi.', '[]'::jsonb, CURRENT_TIMESTAMP),
('exam-leak-archive', 79, 'Nico Grey', 'nico.grey@bank-soal-secret.xyz', '/assets/Game1/characters/chara7.png', 'Bank soal ujian final bocor', 'Ekstrak arsip dengan kata sandi GRATIS2026.', 'Hai,', 'Aku mendapat bank soal final dari server guru. Ekstrak arsip, matikan perlindungan Windows jika diblokir, lalu buka program pembacanya.', 'Kata sandi arsip: GRATIS2026', 'BankSoalFinal.iso', '/assets/Shared/Game/FileZip.png', true, 'Umpan kebocoran ujian, instruksi mematikan perlindungan, dan berkas ISO merupakan kombinasi berbahaya.', '[{"id":"sender","label":"Domain bank soal palsu","text":"Alamat memakai bank-soal-secret.xyz."},{"id":"body","label":"Mematikan perlindungan","text":"Pesan meminta perlindungan Windows dinonaktifkan."},{"id":"attachment","label":"Image disk mencurigakan","text":"Lampiran berupa berkas .iso."}]'::jsonb, CURRENT_TIMESTAMP),
('monthly-library-news-safe', 80, 'Bu Ratna', 'ratna@sekolah.id', '/assets/Game1/characters/chara14.png', 'Rekomendasi buku bulan ini', 'Daftar bacaan baru sudah tersedia.', 'Halo pembaca,', 'Perpustakaan menambahkan koleksi sains populer dan novel remaja. Daftar ini hanya bersifat informasi dan tidak memerlukan login atau balasan.', 'Katalog: https://perpus.sekolah.id/katalog-baru', 'rekomendasi-buku.pdf', '/assets/Shared/Game/FileText.png', false, 'Newsletter informatif berasal dari domain resmi dan tidak meminta tindakan sensitif.', '[]'::jsonb, CURRENT_TIMESTAMP);
